INSERT INTO feature VALUES('rule-conditions','rules','Conditions on a rule','rule-coincidence','partial','notable',NULL,'A rule''s condition is read over its variables: where a port takes an atom, each variable is a hole over the atoms abstracted above it that it may name, a freshness condition `where a # t` or a right side standing outside the abstraction narrowing it, so two rules'' overlap is decided in the second-order reading under the condition it composes: the pair joins there, parts there and is refused `RulesOverlapCondition`, or has no instance the conditions admit and holds without a peak. A rule stated under a row of theories, `under [T, … | r]` open or `under [T, …]` closed, fires only in the rows it describes: two such rules'' overlap is decided in the rows both describe, the meet of their rows, by the rules firing in each of them, and two rows sharing none owe no join; a theory a row names that no block presents, or one named twice, is refused by name. A model of a theory owes a law under a row in every row (#2466).','kernel-term surface-lowering surface-lowering-base theory-levitation theory-computads surface-grammar','corpus/model/desc/atom-occurrence.gandr corpus/pathological/desc/atom-occurrence.gandr corpus/ledger/diagnostics/RulesOverlapCondition.gandr corpus/model/effects/rows.gandr corpus/pathological/effects/rows.gandr crates/kernel-term/src/theory_rules/tests.rs crates/surface-lowering-base/tests/coincide.rs crates/surface-lowering-base/src/description/theory/tests.rs','corpus/ledger/features/rule-conditions.gandr','#2466');
